        .call::<_, serde_json::Value, _, _>(&"a", "fp", || async { Err(HostError::Invalid("no binary".into())) }, "m", &json!({}))
        .await
        .unwrap_err();
    assert!(matches!(connect, CallError::Connect(HostError::Invalid(ref m)) if m == "no binary"));

    let handshake = pool
        .call::<_, serde_json::Value, _, _>(&"b", "fp", refusing_initialize_opener(), "m", &json!({}))
