- [ ] **Step 1: Write the failing test.** In `crates/morphir/tests/mep_contract.rs`:

```rust
//! The MEP contract model in spec/mep compiles and covers the protocol.
use serde_json::Value;
use std::{collections::BTreeSet, path::PathBuf, process::Command};

fn contract_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../spec/mep/contract")
}

/// Compile a copy of the contract in a temporary directory, so the test never
/// writes into the repository and ignores the user's Morphir config.
fn compile_contract() -> Value {
    let work = tempfile::tempdir().unwrap();
    let project = work.path().join("contract");
    copy_dir(&contract_dir(), &project); // write a small recursive copy helper; skip `.morphir` and `build`
    let home = work.path().join("home");
    std::fs::create_dir_all(&home).unwrap();
    let mut command = Command::new(env!("CARGO_BIN_EXE_morphir"));
    command
        .current_dir(&project)
        .args(["compile", "--config", "morphir.toml", "--ir-version", "4", "--types-only"])
        .env("HOME", &home)
        .env("XDG_CONFIG_HOME", home.join(".config"));
    for (key, _) in std::env::vars() {
        if key.starts_with("MORPHIR_") {
            command.env_remove(key);
        }
    }
    let output = command.output().unwrap();
    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
    let ir = project.join(".morphir/out/compile.dest/morphir-ir.json");
    serde_json::from_slice(&std::fs::read(ir).unwrap()).unwrap()
}

const HANDSHAKE_TYPES: &[&str] = &[
    "json", "peer-kind", "peer-info", "describe-params", "initialize-params",
    "initialize-result", "extension-type", "extension-info", "method", "error-code", "rpc-error",
];

#[test]
fn the_contract_covers_the_handshake() {
    let names = type_names(&compile_contract());
    for expected in HANDSHAKE_TYPES {
        assert!(names.contains(*expected), "mep.gleam is missing {expected}; has {names:?}");
    }
    assert_eq!(
        field_labels(&compile_contract(), "initialize-result"),
        ["protocol-version", "extension", "capabilities"]
    );
}
```

Write `type_names` and `field_labels` against the IR v4 JSON shape the CLI emits (open a compiled `examples/gleam/ir-v3` output, or `morphir_core::ir::v4` in `gleam_dogfood.rs`, to see the path from the distribution to module `mep`'s `types` map and a custom type's constructor arguments). Names in IR are kebab-case segment names, as in the constants above. If deserializing into `morphir_core::ir::v4` types is simpler than walking JSON, do that instead and keep the helper signatures.

